// #6a993d795019333734edc22d (#edc22d) AC2 — создание бизнеса: заполнено только «שם העסק» → сохранение заблокировано (кейс BIZ-LC-002).
// spec: specs/business-lifecycle.md (3.1) · seed: tests/seed.admin.spec.ts
// @prod-safe: бизнес не создаётся. Страховка — запрос admin-create-business перехватывается и обрывается (и должен не случиться вовсе).
import * as path from 'path';
import { test, expect } from '../../fixtures';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

test.describe('Создание бизнеса Super Admin — обязательные поля (#6a993d795019333734edc22d)', () => {
  test('только «שם העסק» → сохранение заблокировано, 7 полей подсвечены, введённое сохранено @desktop @prod-safe #6a993d795019333734edc22d', async ({ page }) => {
    let createCalls = 0;
    await page.route('**/functions/v1/admin-create-business', (route) => {
      createCalls++;
      return route.abort();
    });

    await page.goto('/admin/businesses/new');
    await expect(page.getByRole('heading', { level: 1, name: 'יצירת בית עסק' })).toBeVisible();

    const biz = page.getByRole('group', { name: 'פרטי העסק' });
    const contact = page.getByRole('group', { name: 'איש קשר' });
    const manager = page.getByRole('group', { name: 'מנהל/ת החשבון הראשון/ה' });
    const name = biz.getByRole('textbox', { name: 'שם העסק (חובה)' });
    await name.fill('QA-AUTO partial');
    await page.getByRole('button', { name: 'יצירת בית העסק' }).click();

    // AC2 «השמירה נחסמת»: сообщение о блокировке.
    const alert = page.getByRole('alert').filter({ hasText: 'לא ניתן לשמור' });
    await expect(alert).toBeVisible();
    await expect(alert).toContainText('חסרים פרטים בטופס. השדות המסומנים דורשים תיקון.');

    // AC2 «השדה החסר מסומן במקומו»: каждое пустое обязательное поле — aria-invalid и текст ошибки под ним.
    const missing = [
      [biz.getByRole('textbox', { name: 'תחום פעילות (חובה)' }), 'יש להזין את תחום הפעילות'],
      [contact.getByRole('textbox', { name: 'שם איש הקשר (חובה)' }), 'יש להזין את שם איש הקשר'],
      [contact.getByRole('textbox', { name: 'תפקיד איש הקשר (חובה)' }), 'יש להזין את תפקיד איש הקשר'],
      [contact.getByRole('textbox', { name: 'טלפון (חובה)' }), 'יש להזין טלפון של איש הקשר'],
      [contact.getByRole('textbox', { name: 'מייל (חובה)' }), 'יש להזין מייל של איש הקשר'],
      [manager.getByRole('textbox', { name: 'שם מלא (חובה)' }), 'יש להזין את שם מנהל/ת החשבון'],
      [manager.getByRole('textbox', { name: 'מייל (חובה)' }), 'יש להזין את המייל של מנהל/ת החשבון'],
    ] as const;
    for (const [field, error] of missing) {
      await expect(field, error).toHaveAttribute('aria-invalid', 'true');
      await expect(field, error).toHaveAccessibleDescription(error);
    }

    // Фокус на первом пустом поле; AC2 «הערכים שכבר הוזנו נשמרים».
    await expect(biz.getByRole('textbox', { name: 'תחום פעילות (חובה)' })).toBeFocused();
    await expect(name).toHaveValue('QA-AUTO partial');
    await expect(name).not.toHaveAttribute('aria-invalid', 'true');

    // Бизнес не создан: остаёмся на форме, запроса создания не было.
    await expect(page).toHaveURL(/\/admin\/businesses\/new$/);
    expect(createCalls, 'admin-create-business не вызывается').toBe(0);
  });
});
